count = 0
for pathway in data['pathways']:
    pathway_id = pathway.get('id', '')
    if pathway_id in semantic_map:
        pathway.update(semantic_map[pathway_id])
        count += 1

with open('pathways.json', 'w') as f:
    json.dump(data, f, indent=2)

print("Added semantic metadata to {} / {} pathways".format(count, len(data['pathways'])))
